describe('evaluateBudget', () => {
  it('estimates one token for every four bytes', () => {
    expect(evaluateBudget(400, 100)).toEqual({
      bytes: 400,
      estimatedTokens: 100,
      limit: 100,
      marginReserve: 0,
      withinLimit: true,
    });
  });

  it('marks values above the limit as over budget', () => {
    expect(evaluateBudget(404, 100).withinLimit).toBe(false);
  });

  it('reserves tokens from budget with margin reserve', () => {
    expect(evaluateBudget(400, 100, 20)).toEqual({
      bytes: 400,
      estimatedTokens: 100,
      limit: 100,
      marginReserve: 20,
      withinLimit: false,
    });
  });

  it('respects effective limit reduced by margin reserve', () => {
    expect(evaluateBudget(320, 100, 20)).toEqual({
      bytes: 320,
      estimatedTokens: 80,
      limit: 100,
      marginReserve: 20,
      withinLimit: true,
    });
  });

  it('marks as over budget when margin reserve consumes all available tokens', () => {
    expect(evaluateBudget(400, 100, 100).withinLimit).toBe(false);
  });
});

