export type ContextBudget = Readonly<{
  bytes: number;
  estimatedTokens: number;
  limit: number;
  marginReserve: number;
  withinLimit: boolean;
}>;

export const evaluateBudget = (
  bytes: number,
  limit: number,
  marginReserve: number = 0,
): ContextBudget => {
  const estimatedTokens = Math.ceil(bytes / 4);
  const effectiveLimit = limit - marginReserve;
  return {
    bytes,
    estimatedTokens,
    limit,
    marginReserve,
    withinLimit: estimatedTokens <= effectiveLimit,
  };
};
